import{_ as t,o,c as a,a5 as n}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"776批量删除指定文件夹A下文件夹名为B的文件夹下指定名称的文件或文件夹","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["删除指定子文件夹下指定文件及文件夹"]},"headers":[],"relativePath":"md/文件及文件夹批处理/776批量删除指定文件夹A下文件夹名为B的文件夹下指定名称的文件或文件夹.md","filePath":"md/文件及文件夹批处理/776批量删除指定文件夹A下文件夹名为B的文件夹下指定名称的文件或文件夹.md"}'),s={name:"md/文件及文件夹批处理/776批量删除指定文件夹A下文件夹名为B的文件夹下指定名称的文件或文件夹.md"};function e(p,r,_,g,b,l){return o(),a("div",null,[...r[0]||(r[0]=[n('<h3 id="批量删除指定文件夹a下文件夹名为b的文件夹下指定名称的文件或文件夹" tabindex="-1">批量删除指定文件夹A下文件夹名为B的文件夹下指定名称的文件或文件夹 <a class="header-anchor" href="#批量删除指定文件夹a下文件夹名为b的文件夹下指定名称的文件或文件夹" aria-label="Permalink to &quot;批量删除指定文件夹A下文件夹名为B的文件夹下指定名称的文件或文件夹&quot;">​</a></h3><p>有<strong>精确匹配</strong>和模糊匹配两个选项，模糊匹配是文件或文件夹名中包含输入内容的就删除，精确匹配则是输入的内容与文件名或文件夹名完全一样才会删除。文件名可以带格式扩展名，也可以不带，如果存在文件名相同的不同格式的文件，则带上扩展名会更精确。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250617171254175015157450116.png" alt=""></p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>比如A文件夹下有B文件夹，B文件夹下有C文件夹，C文件夹下有D文件夹，需要删除D文件夹下的文件名为123.txt的文件和123的文件夹</p><p>在程序中目标文件夹输入A文件夹路径，子文件夹名称输入D文件夹路径</p><p>选择精确匹配或模糊匹配，然后在目标名称输入框输入123，点击删除即可将文件名为123.txt的文件和123的文件夹删除</p><p>【1】、支持的文件格式：所有</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="📑-文件结构树示意" tabindex="-1">📑 文件结构树示意 <a class="header-anchor" href="#📑-文件结构树示意" aria-label="Permalink to &quot;📑 文件结构树示意&quot;">​</a></h3><p>比如要删除文件夹A下C文件夹下的C1文件夹，或删除C1文件夹下的文件8</p><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250720101433175297767379529.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统</p><p>注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1890.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1890.html</a></p>',19)])])}const c=t(s,[["render",e]]);export{h as __pageData,c as default};
